const artykuly = $input.all()
  .map(item => item.json)
  .filter(a => a.title);

const data = $now.toFormat('dd.MM.yyyy');

// Pusty poranek: wysyłamy krótką informację zamiast ciszy
if (artykuly.length === 0) {
  return [{ json: { wiadomosc: `📰 ${data}: dziś brak nowych artykułów.` } }];
}

const linie = artykuly.map((a, n) =>
  `${n + 1}. ${a.title}\n<${a.link}>`
);

let wiadomosc = `📰 Poranny przegląd, ${data}\n\n` + linie.join('\n\n');

// Discord przyjmuje maksymalnie 2000 znaków
if (wiadomosc.length > 1900) {
  wiadomosc = wiadomosc.slice(0, 1900) + '\n…';
}

return [{ json: { wiadomosc } }];
